import CircularQueue from '../src/utils/CircularQueue'

function createTest(size: number, initWith: number) {
    const testQueue = new CircularQueue<string>(size)
    for (let index = 0; index < initWith; index++) {
        testQueue.push('val:' + (index + 1))
    }

    return testQueue
}

test('Large Circular Queue', () => {
    for (let index = 5; index < 20; index++) {
        expect(createTest(4, index).peek()) //
            .toBe('val:' + (index - 3))
    }
})

test('Basic Circular Queue', () => {
    expect(createTest(2, 10).peek()) //
        .toBe('val:9')

})

test('Basic Circular Queue', () => {
    expect(createTest(2, 1).peek()) //
        .toBe(undefined)
})

test('Basic Circular Queue', () => {
    expect(createTest(2, 2).peek()) //
        .toBe('val:1')
})

test('Basic Circular Queue', () => {
    expect(createTest(2, 3).peek()) //
        .toBe('val:2')
})

import AppsDataStore from '../src/datastore/AppsDataStore'
import OneClickAppDeploymentHelper from '../src/user/oneclick/OneClickAppDeploymentHelper'
import OneClickAppDeployManager, {
    ONE_CLICK_APP_NAME_VAR_NAME,
} from '../src/user/oneclick/OneClickAppDeployManager'
import { IOneClickTemplate } from '../src/models/IOneClickAppModels'

describe('OneClickAppDeployManager', () => {
    test('treats omitted values as an empty array', () => {
        const onDeploymentStateChanged = jest.fn()
        const manager = new OneClickAppDeployManager(
            {} as any,
            {} as any,
            onDeploymentStateChanged
        )

        const template: IOneClickTemplate = {
            captainVersion: 4,
            services: {},
            caproverOneClickApp: {
                displayName: 'Test App',
                instructions: {
                    start: '',
                    end: '',
                },
                variables: [
                    {
                        id: ONE_CLICK_APP_NAME_VAR_NAME,
                        label: 'App Name',
                    },
                ],
            },
        }

        expect(() => manager.startDeployProcess(template)).not.toThrow()
        expect(onDeploymentStateChanged).toHaveBeenCalledWith({
            steps: ['Parsing the template'],
            error: 'App name ($$cap_appname) is required.',
            currentStep: 0,
        })
    })

    describe('checks every app name before it creates anything', () => {
        const template: IOneClickTemplate = {
            captainVersion: 4,
            services: {
                [ONE_CLICK_APP_NAME_VAR_NAME]: { image: 'nginx' },
                [`${ONE_CLICK_APP_NAME_VAR_NAME}-worker`]: { image: 'nginx' },
            },
            caproverOneClickApp: {
                displayName: 'Test App',
                instructions: { start: '', end: 'done' },
                variables: [
                    { id: ONE_CLICK_APP_NAME_VAR_NAME, label: 'App Name' },
                ],
            },
        }

        // The steps that create something; each one only records its call.
        const helper = OneClickAppDeploymentHelper.prototype
        let creates: jest.SpyInstance[]
        beforeEach(() => {
            creates = [
                'createRegisterPromiseProject',
                'createRegisterPromise',
                'createConfigurationPromise',
                'createDeploymentPromise',
            ].map((step) =>
                jest.spyOn(helper, step as any).mockResolvedValue(undefined)
            )
        })
        afterEach(() => jest.restoreAllMocks())

        // Returns every state the deploy reported, after pending steps ran.
        async function deploy(appName: string, existingApps: string[] = []) {
            const onDeploymentStateChanged = jest.fn()
            const appsDataStore = new AppsDataStore(
                {
                    get: (key: string) =>
                        existingApps.includes(key.split('.')[1])
                            ? {}
                            : undefined,
                } as any,
                'captain'
            )
            new OneClickAppDeployManager(
                { getAppsDataStore: () => appsDataStore } as any,
                {} as any,
                onDeploymentStateChanged
            ).startDeployProcess(template, [
                { key: ONE_CLICK_APP_NAME_VAR_NAME, value: appName },
            ])
            await new Promise((resolve) => setImmediate(resolve))
            return onDeploymentStateChanged.mock.calls.map((call) => call[0])
        }

        test.each([
            [
                'a later app name that is too long',
                'a'.repeat(43),
                [],
                `${'a'.repeat(43)}-worker: App Name is not allowed. Only lowercase letters, numbers and single hyphens are allowed, up to 49 characters`,
            ],
            [
                'a later app name that already exists',
                'my-app',
                ['my-app-worker'],
                'my-app-worker: App Name already exists. Please use a different name',
            ],
            [
                'the first app name that already exists',
                'my-app',
                ['my-app'],
                'my-app: App Name already exists. Please use a different name',
            ],
        ])('%s', async (_case, appName, existingApps, error) => {
            expect(await deploy(appName, existingApps)).toEqual([
                { steps: ['Parsing the template'], error, currentStep: 0 },
            ])
            creates.forEach((create) => expect(create).not.toHaveBeenCalled())
        })

        test('names that pass are deployed as before', async () => {
            const states = await deploy('my-app')
            expect(states[states.length - 1]).toMatchObject({
                error: '',
                currentStep: 8,
                successMessage: 'done',
            })
            expect(creates[1].mock.calls.map((call) => call[0])).toEqual([
                'my-app',
                'my-app-worker',
            ])
        })

        test('an error that is not about a name is thrown, not reported as one', () => {
            const manager = new OneClickAppDeployManager(
                {} as any,
                {} as any,
                jest.fn()
            )
            expect(() =>
                manager.startDeployProcess(template, [
                    { key: ONE_CLICK_APP_NAME_VAR_NAME, value: 'my-app' },
                ])
            ).toThrow(TypeError)
            creates.forEach((create) => expect(create).not.toHaveBeenCalled())
        })
    })
})

import express = require('express')
import type { Server } from 'node:http'
import type { AddressInfo } from 'node:net'
import ApiStatusCodes from '../src/api/ApiStatusCodes'
import { IOneClickTemplate } from '../src/models/IOneClickAppModels'
import oneClickRouter from '../src/routes/user/oneclick/OneClickAppRouter'
import OneClickAppDeployManager from '../src/user/oneclick/OneClickAppDeployManager'
import { OneClickDeploymentJobRegistry } from '../src/user/oneclick/OneClickDeploymentJobRegistry'
import Logger from '../src/utils/Logger'

describe('one-click deploy route', () => {
    const template: IOneClickTemplate = {
        captainVersion: 4,
        services: {},
        caproverOneClickApp: {
            displayName: 'Test App',
            instructions: {
                start: '',
                end: '',
            },
            variables: [],
        },
    }

    let server: Server
    let baseUrl: string
    let registry: {
        createJob: jest.Mock
        updateJobProgress: jest.Mock
        removeJob: jest.Mock
    }
    let startDeployProcess: jest.SpyInstance

    beforeEach(async () => {
        registry = {
            createJob: jest.fn(() => 'job-1'),
            updateJobProgress: jest.fn(),
            removeJob: jest.fn(),
        }

        jest.spyOn(
            OneClickDeploymentJobRegistry,
            'getInstance'
        ).mockReturnValue(registry as any)
        startDeployProcess = jest
            .spyOn(OneClickAppDeployManager.prototype, 'startDeployProcess')
            .mockImplementation(() => undefined)
        jest.spyOn(Logger, 'e').mockImplementation(() => undefined)

        const app = express()
        app.use(express.json())
        app.use(function (_req, res, next) {
            res.locals.user = {
                dataStore: {},
                serviceManager: {},
                userManager: {
                    eventLogger: {
                        trackEvent: jest.fn(),
                    },
                },
            }
            next()
        })
        app.use('/user/oneclick', oneClickRouter)

        server = await new Promise<Server>((resolve) => {
            const listeningServer = app.listen(0, () => resolve(listeningServer))
        })

        const address = server.address() as AddressInfo
        baseUrl = `http://127.0.0.1:${address.port}`
    })

    afterEach(async () => {
        await new Promise<void>((resolve, reject) => {
            server.close((error) => {
                if (error) {
                    reject(error)
                    return
                }
                resolve()
            })
        })
        jest.restoreAllMocks()
    })

    async function postDeploy(body: Record<string, unknown>) {
        return fetch(`${baseUrl}/user/oneclick/deploy`, {
            method: 'POST',
            headers: {
                'content-type': 'application/json',
            },
            body: JSON.stringify(body),
        })
    }

    test('defaults omitted values to an empty array', async () => {
        const response = await postDeploy({
            template,
            templateName: 'TEMPLATE_ONE_CLICK',
        })
        const body = (await response.json()) as {
            status: number
            data: { jobId: string }
        }

        expect(response.status).toBe(200)
        expect(body.status).toBe(ApiStatusCodes.STATUS_OK)
        expect(body.data.jobId).toBe('job-1')
        expect(startDeployProcess).toHaveBeenCalledWith(template, [])
        expect(registry.createJob).toHaveBeenCalledTimes(1)
        expect(registry.removeJob).not.toHaveBeenCalled()
    })

    test('rejects non-array values before creating a job', async () => {
        const response = await postDeploy({
            template,
            values: {},
            templateName: 'TEMPLATE_ONE_CLICK',
        })
        const body = (await response.json()) as {
            status: number
            description: string
        }

        expect(response.status).toBe(200)
        expect(body.status).toBe(ApiStatusCodes.ILLEGAL_PARAMETER)
        expect(body.description).toBe('Values must be an array')
        expect(registry.createJob).not.toHaveBeenCalled()
        expect(startDeployProcess).not.toHaveBeenCalled()
    })

    test('removes a newly-created job when deployment startup throws', async () => {
        startDeployProcess.mockImplementationOnce(() => {
            throw new Error('startup failed')
        })

        const response = await postDeploy({
            template,
            values: [],
            templateName: 'TEMPLATE_ONE_CLICK',
        })

        expect(response.status).toBe(500)
        await response.text()
        expect(registry.createJob).toHaveBeenCalledTimes(1)
        expect(registry.removeJob).toHaveBeenCalledWith('job-1')
    })
})

