function backupTests() {
    test('No backup file', () => {
        const bk = new BackupManager()
        return Promise.resolve()
            .then(function () {
                return bk.checkAndPrepareRestoration()
            })
            .then(function (data) {
                expect(data).toBeFalsy()
            })
    })

    test('Restores malformed backup with nested data/data layout', async () => {
        const sourceDirectory = '/tmp/caprover-malformed-backup-test'
        const malformedDataDirectory = `${sourceDirectory}/data/data`

        await remove(sourceDirectory)

        try {
            await outputJson(`${sourceDirectory}/meta/backup.json`, {
                salt: 'test-salt',
                nodes: [
                    {
                        nodeId: '123456789',
                        type: 'manager',
                        isLeader: true,
                        hostname: 'test',
                        architecture: 'x86_64',
                        operatingSystem: 'linux',
                        nanoCpu: 8000000000,
                        memoryBytes: 8241434624,
                        dockerEngineVersion: '18.09.2',
                        ip: '123.123.123.123',
                        state: 'ready',
                        status: 'active',
                    },
                ],
            })
            await outputJson(`${malformedDataDirectory}/config-captain.json`, {
                appDefinitions: {
                    pers1: {
                        nodeId: '123456789',
                    },
                },
            })
            await ensureDir(`${malformedDataDirectory}/shared-logs`)
            await outputJson(
                `${malformedDataDirectory}/shared-logs/should-not-restore.json`,
                { ignored: true }
            )

            await tar.c(
                {
                    file: BACKUP_FILE_PATH_ABSOLUTE,
                    cwd: sourceDirectory,
                },
                ['./']
            )

            const bk = new BackupManager()
            await bk.checkAndPrepareRestoration()

            expect(
                await pathExists(
                    `${CaptainConstants.restoreDirectoryPath}/data/config-captain.json`
                )
            ).toBe(true)
            expect(
                await pathExists(
                    `${CaptainConstants.restoreDirectoryPath}/data/data/config-captain.json`
                )
            ).toBe(false)
            expect(
                await pathExists(
                    `${CaptainConstants.restoreDirectoryPath}/data/shared-logs`
                )
            ).toBe(false)

            const ret = (await readJson(
                CaptainConstants.restoreDirectoryPath +
                    '/restore-instructions.json'
            )) as RestoringInfo

            expect(ret.nodesMapping).toEqual([
                {
                    newIp: 'CURRENT_NODE_DONT_CHANGE',
                    oldIp: '123.123.123.123',
                    privateKeyPath: '',
                    user: '',
                },
            ])
            expect(ret.oldNodesForReference[0].appsLockOnThisNode).toEqual([
                'pers1',
            ])
        } finally {
            await remove(sourceDirectory)
        }
    })

    test('Rejects malformed nested backup without config-captain.json', async () => {
        const sourceDirectory =
            '/tmp/caprover-malformed-backup-missing-config-test'
        const malformedDataDirectory = `${sourceDirectory}/data/data`

        await remove(sourceDirectory)

        try {
            await outputJson(`${sourceDirectory}/meta/backup.json`, {
                salt: 'test-salt',
                nodes: [],
            })
            await ensureDir(malformedDataDirectory)

            await tar.c(
                {
                    file: BACKUP_FILE_PATH_ABSOLUTE,
                    cwd: sourceDirectory,
                },
                ['./']
            )

            const bk = new BackupManager()
            await expect(bk.checkAndPrepareRestoration()).rejects.toThrow()

            expect(
                await pathExists(
                    CaptainConstants.restoreDirectoryPath +
                        '/restore-instructions.json'
                )
            ).toBe(false)
        } finally {
            await remove(sourceDirectory)
        }
    })

    test('Test backup file', () => {
        const bk = new BackupManager()
        return Promise.resolve()
            .then(function () {
                return copy(
                    `${__dirname}/backup.tar`,
                    BACKUP_FILE_PATH_ABSOLUTE
                )
            })
            .then(function () {
                return bk.checkAndPrepareRestoration()
            })
            .then(function () {
                return readJson(
                    CaptainConstants.restoreDirectoryPath +
                        '/restore-instructions.json'
                )
            })
            .then(function (ret: RestoringInfo) {
                const expectedValue = {
                    nodesMapping: [
                        {
                            newIp: 'CURRENT_NODE_DONT_CHANGE',
                            oldIp: '123.123.123.123',
                            privateKeyPath: '',
                            user: '',
                        },
                    ],
                    oldNodesForReference: [
                        {
                            nodeData: {
                                nodeId: '123456789',
                                type: 'manager',
                                isLeader: true,
                                hostname: 'test',
                                architecture: 'x86_64',
                                operatingSystem: 'linux',
                                nanoCpu: 8000000000,
                                memoryBytes: 8241434624,
                                dockerEngineVersion: '18.09.2',
                                ip: '123.123.123.123',
                                state: 'ready',
                                status: 'active',
                            },
                            appsLockOnThisNode: ['pers1'],
                        },
                    ],
                }
                expect(isDeepStrictEqual(ret, expectedValue)).toBe(true)
                ret.nodesMapping[0].oldIp += ' '
                expect(isDeepStrictEqual(ret, expectedValue)).toBe(false)
            })
    })
}

import * as yaml from 'yaml'
import { IDockerComposeService } from '../models/IOneClickAppModels'
import Utils from './Utils'

export default class DockerComposeToServiceOverride {
    /**
     * Converts the unsupported docker compose parameters to CapRover service override definition.
     * Port, replicas, env vars, volumes, and image are supplied through CapRover definition,
     * network will be set to captain-overlay restart_policy is not generally needed,
     * by default docker services restart automatically.
     * Only parse parameters that are not from the aforementioned list.
     * The only useful parameter that we are parsing at the moment is hostname: https://github.com/caprover/caprover/issues/404
     *
     * @param docker compose service definition
     * @returns the override service definition in yaml format
     */
    static convertUnconsumedComposeParametersToServiceOverride(
        compose: IDockerComposeService
    ) {
        const overrides = [] as any[]
        overrides.push(DockerComposeToServiceOverride.parseHostname(compose))
        overrides.push(DockerComposeToServiceOverride.parseCapAdd(compose))
        overrides.push(DockerComposeToServiceOverride.parseCommand(compose))
        // Add more overrides here if needed

        let mergedOverride = {} as any
        overrides.forEach((o) => {
            mergedOverride = Utils.mergeObjects(mergedOverride, o)
        })
        if (Object.keys(mergedOverride).length === 0) {
            return undefined
        }

        return yaml.stringify(mergedOverride)
    }

    private static parseCommand(compose: IDockerComposeService) {
        const override = {} as any

        function parseDockerCMD(cmdString: string) {
            // Matches sequences inside quotes or sequences without spaces
            const regex = /[^\s"']+|"([^"]*)"|'([^']*)'/g
            let match
            const args = []

            while ((match = regex.exec(cmdString))) {
                // If matched quotes, add the first group that is not undefined
                if (match[1]) {
                    args.push(match[1])
                } else if (match[2]) {
                    args.push(match[2])
                } else {
                    args.push(match[0])
                }
            }

            return args
        }

        if (compose.command) {
            override.TaskTemplate = {
                ContainerSpec: {
                    Command: Array.isArray(compose.command)
                        ? compose.command
                        : parseDockerCMD(compose.command),
                },
            }
        }

        return override
    }

    private static parseHostname(compose: IDockerComposeService) {
        const override = {} as any
        const hostname = compose.hostname ? `${compose.hostname}`.trim() : ''
        if (compose.hostname) {
            override.TaskTemplate = {
                ContainerSpec: {
                    Hostname: hostname,
                },
            }
        }

        return override
    }

    private static parseCapAdd(compose: IDockerComposeService) {
        const override = {} as any
        if (!!compose.cap_add && Array.isArray(compose.cap_add)) {
            const capabilityAdd = compose.cap_add
                .map((cap) => cap.toUpperCase())
                .map((cap) => (cap.startsWith(`CAP`) ? cap : `CAP_${cap}`))
            override.TaskTemplate = {
                ContainerSpec: {
                    CapabilityAdd: capabilityAdd,
                },
            }
        }

        return override
    }
}

